const binaryProperty = $input.item.binary.data ? 'data' : 'file';
const buffer = await this.helpers.getBinaryDataBuffer(0, binaryProperty);
return [{
  json: {
    mimeType: $input.item.binary[binaryProperty].mimeType,
    imageData: buffer.toString('base64')
  }
}];

