const text = $json.candidates[0].content.parts[0].text;
let cleanText = text.replace(/```json\s*/g, '').replace(/```\s*/g, '').trim();

try {
  const result = JSON.parse(cleanText);
  return [{
    json: {
      status: "success",
      structured_data: {
        hemoglobin: result.hemoglobin || 'N/A',
        blood_sugar: result.blood_sugar || 'N/A',
        cholesterol: result.cholesterol || 'N/A'
      },
      raw_text: result.summary || 'No summary available',
      risks: result.risks || [],
      diet_plan: result.diet_plan || [],
      exercise_plan: result.exercise_plan || []
    }
  }];
} catch (e) {
  return [{
    json: {
      status: "error",
      raw_text: "Failed to parse AI response",
      structured_data: { hemoglobin: 'N/A', blood_sugar: 'N/A', cholesterol: 'N/A' },
      risks: [],
      diet_plan: [],
      exercise_plan: []
    }
  }];
}
